  if (cm) {
    const c = dsCondRows().find(x => x.id === cm[1]);
    if (!c) return 'такого условия больше нет';
    if (condClosed(c) || c.status === 'expired') return `условие ${condBadge(c)[1]}${c.last_event?.at ? ' ' + _ddmmDot(c.last_event.at) : ''}`;
    if (c.status === 'fired') return `условие сработало ${_ddmmDot(c.fired_at)} — отметка в «Сделать» на «Действиях»`;
    return null;
  }
  const tf = String(a.target_file || '').split('/').pop();
  const recs = [...(state.data.forecasts || []), ...(state.data.scenarioYamls || [])];
