  const ends = Object.entries(horizonEnds).filter(([, v]) => /^\d{4}-\d{2}-\d{2}/.test(v || '')).map(([k, v]) => [k, String(v).slice(0, 10)]);
  if (!ends.length || !/^\d{4}-\d{2}-\d{2}/.test(todayIso || '')) return null;
