  const total = live ? xi.pnl_rub + (hold.value_rub - xi.market_value_rub) : xi.pnl_rub;
  const value = hold?.value_rub ?? xi.market_value_rub;
  const rc = xi === xiAll ? (port?.reconciliation?.balance_vs_trades?.positions || []).find(x => x.ticker === ticker) : null;
  const avg = rc?.avg_cost_trades ?? hold?.avg_cost_rub ?? null;
