  const divs = (xi.dividends_rub || 0) + (xi.coupons_rub || 0);
  const realized = unreal != null ? total - divs - unreal : null;
  const hadSells = xi.n_sells != null ? xi.n_sells > 0 : (xi.sell_total_rub != null ? xi.sell_total_rub > 0 : realized != null && Math.abs(realized) >= Math.max(1, 0.005 * (xi.buy_total_rub || 0)));
