  return [hadSells && realized != null ? _kv('Прибыль по сделкам', fmtRub(realized), cls(realized)) : null,
    xi.dividends_rub ? _kv('Получено дивидендов', fmtRub(xi.dividends_rub)) : null,
    unreal != null ? _kv('Текущая прибыль', fmtRub(unreal), cls(unreal)) : null, tN];
