// ❓ Справка — части tools/assets/help/viewer/NN-slug.md (раздел = файл; правятся только в репо, на сервер едут
// с assets/ деплоем). Грузятся ui-kit uiHelpOpen({files}) и показываются общим читателем по разделам.
// SYNC: контент справки — в частях; технический ракурс — в docs/investment/portfolio-workflow-guide.md (§5.7).
// Менять оба (правило в CLAUDE.md). Части под паролем — поэтому параметры передаются явно, а не через реестр UI_HELP.
// Ссылки вьюера открывают справку по якорю {#id} заголовка: run, models, modes, fresh, tabs, now, now-new, gates,
// conditions, conditions-priority, site, site-build, site-journal, site-push, limits.
// v3.20.0: «Mode N» в текстах советника → «разбор бумаги (Mode 4)», ссылка на таблицу режимов (якорь modes).
// Номер остаётся: по нему владелец просит Claude запустить режим.
const MODE_RU = CL.words('mode_codes');   // ключи — коды режимов (с legacy «4»)
const _MODE_RE = /\bMode\s*([1-9][ab]?)((?:\s*\/\s*[1-9][ab]?)*)(-разбор[а-я]*)?/g;
const HELP_PARTS = ['00-about', '01-run', '02-models', '03-fresh', '04-tabs', '05-now', '06-gates',
  '07-conditions', '08-site', '09-limits', '10-new'].map(n => `./assets/help/viewer/${n}.md`);
function openHelpAt(anchor, opener) {
  uiHelpOpen('portfolio', opener || null, { title: 'Портфель', kicker: 'Справка по системе', acc: '--c-1',
    files: HELP_PARTS, sections: true, auth: true, at: anchor || null });
}
function openModesHelp(opener) { openHelpAt('modes', opener); }
function openGatesHelp(opener) { openHelpAt('gates', opener); }
function _modeLinkify(root) {
  if (!root) return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
    acceptNode: (n) => !/Mode\s*[1-9]/.test(n.nodeValue) || n.parentElement.closest('button, a, code, pre, input, textarea, .mode-lnk, .uh-overlay')
      ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT });
  const nodes = [];
  while (walker.nextNode()) nodes.push(walker.currentNode);
  for (const n of nodes) {
    const t = n.nodeValue, frag = document.createDocumentFragment();
    let last = 0, m;
    _MODE_RE.lastIndex = 0;
    while ((m = _MODE_RE.exec(t))) {
      const nums = [m[1], ...(m[2] || '').split('/').map(x => x.trim()).filter(Boolean)];
      const words = nums.map(k => MODE_RU[k] || MODE_RU[k[0]]).filter(Boolean);
      if (!words.length) continue;
      frag.append(t.slice(last, m.index));
      frag.append(el('button', { type: 'button', class: 'mode-lnk', title: `Mode ${nums.join('/')} — что это за режим, справка`,   // код режима — только в подсказке (R27)
        onclick: (ev) => { ev.stopPropagation(); openModesHelp(ev.currentTarget); } },
        [...new Set(words)].join(' / ')));
      last = m.index + m[0].length;
    }
    if (!last) continue;
    frag.append(t.slice(last));
    n.replaceWith(frag);
  }
}

