const PF_LEVEL = { block: ['block', 'Блок'], warning: ['warn', 'Внимание'] };
let pfLastFiles = null;     // для «Пересобрать, приняв кэш-расхождение» без повторного выбора файлов
const pfDate = (s) => /^\d{4}-\d{2}-\d{2}/.test(s || '') ? `${s.slice(8, 10)}.${s.slice(5, 7)}.${s.slice(0, 4)}` : (s || '');
const pfSize = (n) => n >= 1048576 ? (n / 1048576).toFixed(1).replace('.', ',') + ' МБ' : Math.max(1, Math.round(n / 1024)) + ' КБ';

