      const re = el('button', { type: 'button', class: 'ui-btn sm ghost pf-split-rebuild', onclick: (e) => { e.currentTarget.disabled = true; pfStart(box, pfLastFiles, opts, $('#pf-msg')); } }, 'Пересобрать');
