      snapshot_keys: [...snap].sort(), stock_keys: [...stock].sort(), first_buy: [...first].sort(),
      plan: dsPlanCtx(port), last_trade_at: dsLastTradeAt().trade, last_sell_at: dsLastTradeAt().sell, last_buy_at: dsLastTradeAt().buy, buys_at: dsLastTradeAt().buys, plan_changed_at: dsPlanChangedAt(), maturities: dsMaturities(),
