// ========== Мой план на сайте (v3.64.0): plan.json через hub-api /api/pv/*, окно правки, журнал ==========
// Решения владельца 27.10 (numbers-exit-plan.md §5): статус бумаги — ручное поле плана, рядом вердикт обзора;
// правка без причины разрешена, но в журнале помечается «без причины». Все изменённые поля — одним пакетным POST (changes).
async function pvApi(path, body) {
  const init = body
    ? { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json' }, body: JSON.stringify(body), cache: 'no-store' }
    : { headers: { Accept: 'application/json' }, cache: 'no-store' };
  let r;
  try { r = await authFetch(state.httpBase + path, init); } catch (e) { return { status: 0, j: null }; }
  let j = null;
  try { j = await r.json(); } catch (e) {}
  return { status: r.status, j };
}
async function loadPlan() {
  const P = state.plan;
  if (state.mode !== 'http') { Object.assign(P, { plan: null, hash: null, status: 'local' }); return; }
  const was = P.status;
  try {
    const { status, j } = await pvApi('api/pv/plan');
    if (status === 200 && j && j.plan) Object.assign(P, { plan: j.plan, hash: j.hash || null, status: 'ok' });
    else if (status === 404) Object.assign(P, { plan: null, hash: null, status: 'none' });
    else Object.assign(P, { plan: null, hash: null, status: 'error' });
  } catch (e) {
    Object.assign(P, { plan: null, hash: null, status: 'error' });
  }
  if (P.status === 'ok') {     // v3.88.0: снапшот всегда считается от плана сайта; раздел «Доли и цели» перерисовать
    liveRebuild();             // копия с живыми ценами: классы фондов — из плана
    planApplyAll();
    if (was === 'ok' && state.currentTab === 'ie-model') { const y = window.scrollY; renderTabContent(); if (document.body.style.position !== 'fixed' && y) window.scrollTo(0, y); }
  }
  if (was !== P.status) {      // кнопки «изменить» появились — перерисовать раздел и карточку
    if (['ie-model', 'bonds', 'funds', 'pfbuild', 'positions', 'actions', 'today'].includes(state.currentTab)) { const y = window.scrollY; renderTabContent(); if (document.body.style.position !== 'fixed' && y) window.scrollTo(0, y); }
    if (cardStack.length) renderCards();
  }
}
