  const nn = f.note || null, cn = (ctx.curNote || null) !== nn;
  if (!cs && !cn) { _miniToast('Нечего сохранять'); return; }
  const ch = { ticker: t, ...(cs ? { share_pct: next } : {}), ...(cn ? { note_ie: nn } : {}), reason: nn };   // причина = заметка IE
