  for (const r of rows) r.calm = r.d.status === 'same' || r.d.status === 'skipped';
  const acts = rows.filter(r => !r.calm);
  const reasonRows = model ? acts.filter(r => r.d.status === 'new' || r.d.status === 'removed' || (r.d.status === 'changed' && r.d.share)) : [];
  const nHeld = rows.filter(r => r.held).length;
  const under = cardStack.length ? $('#card-layer').lastElementChild : null;
  const n = under ? 2 : 1;
  const phone = matchMedia('(max-width:640px)').matches;
