  const reason = el('input', { type: 'text', class: 'fld', id: 'plan-reason', maxlength: '300', autocomplete: 'off' });
  const flds = o.fields.map(mkInp).map(c => el('div', { class: 'ui-field plan-fld' }, el('label', { class: 'fld-lbl' }, c.f.lbl), c.inp));
