async function planSharesSave(layer) {
  const ctx = layer.__shares;
  const changes = [];
  for (const { f, inp } of ctx.items) {
    const raw = String(inp.value).trim().replace(',', '.');
    let next = null;
    if (raw !== '') {
      const p = +raw;
      if (isNaN(p) || p < 0 || p > 100) { _miniToast(`${f.aria}: число от 0 до 100`); inp.focus(); return; }
      next = _pctToShare(p);
    }
    const orig = f.cur == null ? null : _pctToShare(f.cur);
    if (orig == null ? next == null : (next != null && Math.round(orig * 1e4) === Math.round(next * 1e4))) continue;
    changes.push({ path: f.path, value: next });
  }
  if (!changes.length) { _miniToast('Нечего сохранять — поля не менялись'); return; }
  // матрица «валюта × класс» — производная: в тот же пакет дописываем изменившиеся ячейки
  const nc = {}, nb = {};
  for (const ch of changes) {
    let m;
    if ((m = /^classes\.([^.]+)\.share$/.exec(ch.path))) nc[m[1]] = ch.value;
    else if ((m = /^bond_buckets\.(.+)\.share$/.exec(ch.path))) nb[m[1]] = ch.value;
  }
  changes.push(...planMatrixDerivedChanges(nc, nb));
  const saveBtn = layer.querySelector('[data-act="plan-save"]');
  planSaving = true; if (saveBtn) saveBtn.disabled = true;
  try {
    const r = await planSetBatch(changes, ctx.reason.value.trim() || null, ctx.okTxt || 'Сохранено');
    if (r.ok) { planEditClose(); renderTabContent(); }
  } finally { planSaving = false; if (saveBtn) saveBtn.disabled = false; }
}
